const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'$'+Number(n||0).toLocaleString('en-US');
const date=n=>new Date(n).toLocaleString();
const categories=['Design','Development','Marketing','Founders','Consulting'];
let people=[],session=null,account=null,category='All people',period='all',query='',refreshing=false,bidRequest=null,toastTimer;
const options=selected=>categories.map(c=>'<option '+(c===selected?'selected':'')+'>'+c+'</option>').join('');
async function api(path,body,method='POST'){const res=await fetch(path,body===undefined?{}:{method,headers:{'content-type':'application/json'},body:JSON.stringify(body)});const data=await res.json();if(!res.ok)throw Object.assign(new Error(data.error||'Unable to complete request.'),{status:res.status});return data;}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function signin(){const link=document.createElement('a');link.href='/signin-with-chatgpt?return_to='+encodeURIComponent('/account');link.target='_top';document.body.appendChild(link);link.click();link.remove();}
function avatar(p){const initials=esc(p.name.split(' ').map(x=>x[0]).slice(0,2).join(''));return '<div class="avatar">'+(p.photo?'<img src="'+esc(p.photo)+'" alt="'+esc(p.name)+'" loading="lazy"><span hidden>'+initials+'</span>':initials)+'</div>';}
function imageFallbacks(){document.querySelectorAll('.avatar img').forEach(img=>img.onerror=()=>{img.hidden=true;img.nextElementSibling.hidden=false;});}
function footer(){return '<footer><a class="brand" href="/">linkdid<span class="ai">.ai</span></a><a href="/about">About</a><a href="/billing">Crypto payments</a><a href="/support">Support</a><span>Independent. Not affiliated with LinkedIn.</span><button class="text-btn" data-rules>Rules & transparency ↗</button><span>© 2026 Linkdid</span></footer>';}
function rulesBindings(){document.querySelectorAll('[data-rules]').forEach(b=>b.onclick=()=>$('#rules-dialog').showModal());}
function sortedVisible(){return people.filter(p=>(category==='All people'||p.category===category)&&(!query||(p.name+' '+p.headline+' '+p.category).toLowerCase().includes(query))&&(period==='all'||p.today>0)).sort((a,b)=>period==='today'?b.today-a.today||a.created-b.created||a.id.localeCompare(b.id):a.rank-b.rank);}
function renderRows(){const rows=sortedVisible();$('#count').textContent=rows.length;$('#profiles').innerHTML=rows.length?rows.map(p=>{const rank=period==='all'?p.rank:people.filter(x=>x.today>0).sort((a,b)=>b.today-a.today||a.created-b.created||a.id.localeCompare(b.id)).findIndex(x=>x.id===p.id)+1;return '<article class="profile '+(rank===1?'first':'')+'"><span class="rank">#'+rank+'</span>'+avatar(p)+'<div><div class="person-name"><a class="profile-name" href="/profile/'+p.id+'">'+esc(p.name)+'</a><span class="in">in</span></div><p class="headline">'+esc(p.headline)+'</p><div class="meta"><span class="tag">'+esc(p.category)+'</span><span>'+esc(p.location)+'</span><a href="/profile/'+p.id+'">See details ↗</a></div></div><div class="bid-area"><div class="bid-total">'+money(period==='today'?p.today:p.bid)+'</div><span>'+(period==='today'?'today · sandbox':'total · sandbox')+'</span><button class="bid-button" data-bid="'+p.id+'">'+(account?.profile?.id===p.id?'Top up':'Outbid')+' ↗</button></div></article>'}).join(''):'<div class="page-state"><h2>'+(people.length?'No matching profiles yet.':'Be the first in the spotlight.')+'</h2><p>'+(people.length?'Try another category, name, or time period.':'Create your profile to start the leaderboard.')+'</p><a class="button dark" href="/account">Create your profile ↗</a></div>';document.querySelectorAll('[data-bid]').forEach(b=>b.onclick=()=>openBid(people.find(p=>p.id===b.dataset.bid)));imageFallbacks();}
function updateEntry(){const value=Number($('#entry-amount').value),me=account?.profile;$('#claim-rank').textContent='#'+(people.filter(p=>p.id!==me?.id&&(p.bid>value||(p.bid===value&&p.created<=(me?.created||Infinity)))).length+1);}
function home(){document.title='Linkdid — Professional Spotlight';$('#app').innerHTML='<div class="filters" id="filters" aria-label="Filter by specialty">'+['All people',...categories].map(c=>'<button class="filter '+(c===category?'active':'')+'" aria-pressed="'+(c===category)+'">'+c+'</button>').join('')+'</div><section class="claim-surface"><div class="ranking-switch" aria-label="Ranking period"><button data-period="all" class="'+(period==='all'?'active':'')+'" aria-pressed="'+(period==='all')+'">All-time</button><button data-period="today" class="'+(period==='today'?'active':'')+'" aria-pressed="'+(period==='today')+'">Today</button></div><h1>Claim <span id="claim-rank">#1</span> for <span class="amount-control"><button id="less" aria-label="Decrease bid">−</button><span class="currency">$</span><input id="entry-amount" type="number" min="1" max="1000000" step="1" value="'+((people[0]?.bid||0)+1)+'" aria-label="Total sandbox bid"><button id="more" aria-label="Increase bid">+</button></span></h1><form id="quick-claim"><label class="url-entry"><span class="in">in</span><input id="entry-url" type="url" placeholder="Your LinkedIn profile URL" aria-label="LinkedIn profile URL" value="'+esc(account?.profile?.url||'')+'" required></label><select id="entry-category" aria-label="Category" required><option value="">Choose a category</option>'+options(account?.profile?.category)+'</select><button class="button dark">Claim rank ↗</button></form><p class="claim-note">All-time placement stays until you’re outbid. Today’s activity is measured in UTC.</p></section><div class="demo-bar"><span><b>Sandbox mode</b> · Saved profiles and simulated bids. No money is charged.</span><button id="refresh">Refresh ↻</button></div><section class="leaderboard"><div class="board-heading"><h2>The leaderboard <span id="count"></span></h2><span class="sponsored">Sponsored placement · sandbox</span></div><div class="search-row"><label class="search"><span>⌕</span><input id="search" type="search" value="'+esc(query)+'" placeholder="Search people or skills" aria-label="Search profiles"></label><span>Highest '+(period==='today'?'daily':'total')+' bid first ↓</span></div><div id="profiles"></div><div class="board-footer"><span>Ranked by bid, not expertise.</span><span class="refresh-note" id="refresh-note">Updates every 30 seconds</span></div></section>'+footer();renderRows();rulesBindings();$('#search').oninput=e=>{query=e.target.value.toLowerCase();renderRows()};document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{category=b.textContent;home()});document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{period=b.dataset.period;home()});$('#entry-amount').oninput=updateEntry;$('#less').onclick=()=>{$('#entry-amount').value=Math.max(1,Number($('#entry-amount').value)-1);updateEntry()};$('#more').onclick=()=>{$('#entry-amount').value=Math.min(1000000,Number($('#entry-amount').value)+1);updateEntry()};$('#refresh').onclick=()=>refresh(true);$('#quick-claim').onsubmit=e=>{e.preventDefault();if(!session?.user){signin();return}if(!account?.profile){location.href='/account?url='+encodeURIComponent($('#entry-url').value)+'&category='+encodeURIComponent($('#entry-category').value);return}if($('#entry-url').value.replace(/\/$/,'').toLowerCase()!==account.profile.url.toLowerCase()){toast('Edit your LinkedIn URL in My dashboard first.');return}if($('#entry-category').value!==account.profile.category){toast('Update your category in My dashboard first.');return}const total=Number($('#entry-amount').value);if(!Number.isSafeInteger(total)||total<=account.profile.bid||total>1000000){toast('Choose a valid total above your current bid.');return}openBid(null,total-account.profile.bid);};}
async function refresh(manual=false){if(refreshing)return;refreshing=true;try{const data=await api('/api/profiles');people=data.profiles;if(session?.user)account=await api('/api/account');if(location.pathname==='/'){renderRows();updateEntry();$('#refresh-note').textContent='Updated '+new Date().toLocaleTimeString()}if(manual)toast('Rankings refreshed.');}catch(e){if(manual)toast(e.message);else if($('#refresh-note'))$('#refresh-note').textContent='Refresh unavailable. Try again.';}finally{refreshing=false}}
function bidPreview(){const amount=Number($('#bid-form').elements.amount.value),p=account?.profile;if(!p)return;const total=p.bid+amount,rank=people.filter(x=>x.id!==p.id&&(x.bid>total||(x.bid===total&&x.created<=p.created))).length+1;$('#bid-preview').textContent=Number.isSafeInteger(amount)&&amount>0&&amount<=1000000?money(total)+' total → #'+rank+' overall':'Enter a whole-dollar amount from $1 to $1,000,000.';}
function openBid(target=null,amount=null){if(!session?.user){signin();return}if(!account?.profile){location.href='/account';return}bidRequest=null;$('#bid-error').textContent='';const p=account.profile;$('#bid-description').textContent=p.name+' · Current total '+money(p.bid);$('#bid-form').elements.amount.value=amount??Math.max(1,(target?.bid??people[0]?.bid??0)+1-p.bid);bidPreview();$('#bid-dialog').showModal();}
$('#bid-form').elements.amount.oninput=()=>{bidRequest=null;bidPreview()};
$('#bid-form').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('[type=submit]'),amount=Number(form.elements.amount.value);if(!Number.isSafeInteger(amount)||amount<1||amount>1000000)return;button.disabled=true;$('#bid-error').textContent='';bidRequest=bidRequest||{id:crypto.randomUUID(),amount};try{await api('/api/bid',bidRequest);bidRequest=null;await refresh();$('#bid-dialog').close();if(location.pathname==='/account')dashboard();else if(location.pathname.startsWith('/profile/'))profilePage();toast('Sandbox bid saved. No money was charged.');}catch(err){$('#bid-error').textContent=err.message;}finally{button.disabled=false;}};
function dashboard(){document.title='My dashboard — Linkdid';if(!session?.user){$('#app').innerHTML='<section class="page-state"><h1>Your Linkdid account.</h1><p>Sign in to save your profile, track bids, and receive outbid notifications.</p><a class="button dark" href="/signin-with-chatgpt?return_to=%2Faccount" target="_top">Sign in with ChatGPT</a></section>'+footer();rulesBindings();return}
const p=account?.profile,n=account?.notifications||[],b=account?.bids||[],draft=new URLSearchParams(location.search);$('#app').innerHTML='<section class="account-wrap"><h1>Your spotlight, managed.</h1><p>'+esc(session.user.email)+'</p><div class="account-subnav"><a href="/">← Leaderboard</a><a href="/billing">Payments</a><a href="/support">Support</a><button class="text-btn" id="account-refresh">Refresh dashboard ↻</button><a href="/signout-with-chatgpt?return_to=%2F" target="_top">Sign out</a></div><div class="status-message">This dashboard tracks sandbox bids. <a href="/billing">Manage crypto payments</a> or <a href="/paid">view the paid leaderboard</a>. LinkedIn photo import is not connected.</div><div class="stats-grid"><div class="stat"><strong>'+(account?.rank?'#'+account.rank:'—')+'</strong><span>All-time rank</span></div><div class="stat"><strong>'+money(p?.bid)+'</strong><span>Sandbox total</span></div><div class="stat"><strong>'+(account?.stats?.clicks||0)+'</strong><span>Outbound clicks</span></div></div><div class="account-grid"><div><section class="panel"><h2>'+(p?'Edit your profile':'Create your profile')+'</h2><form id="profile-form"><label>Your name<input name="name" required maxlength="60" value="'+esc(p?.name)+'"></label><label>What do you do?<input name="headline" required maxlength="160" value="'+esc(p?.headline)+'"></label><label>LinkedIn profile URL<input name="url" type="url" required value="'+esc(p?.url||draft.get('url'))+'" placeholder="https://www.linkedin.com/in/your-name"></label><label>Category<select name="category">'+options(p?.category||draft.get('category'))+'</select></label><label>Location<input name="location" maxlength="80" value="'+esc(p?.location)+'" placeholder="City, country"></label><p id="profile-error" class="error-message" role="alert"></p><button class="button dark">Save profile</button></form></section><section class="panel"><h2>Your profile photo</h2>'+(p?avatar(p)+'<form id="photo-form"><label>Upload a photo<input type="file" name="photo" accept="image/png,image/jpeg,image/webp" required></label><p>PNG, JPEG, or WebP · maximum 2 MB. Use a photo you have permission to publish.</p><p id="photo-error" class="error-message" role="alert"></p><button class="secondary-btn">Upload photo</button></form>':'<p>Save your profile first, then upload your photo.</p>')+'</section><section class="panel"><h2>Connections</h2><div class="setup-row"><b>LinkedIn photo import</b><span>Not connected</span></div><p>Requires a LinkedIn Developer App with sign-in access. Upload your photo above in the meantime.</p><div class="setup-row"><b>Crypto payments</b><a href="/billing">Open payments →</a></div><p>Manage crypto checkout, payment status, and receipts on the Payments page. Checkout stays unavailable until the merchant activates it.</p></section></div><div><section class="panel"><h2>Your listing</h2>'+(p?'<p>'+esc(p.name)+' · '+esc(p.category)+'</p><div class="profile-actions"><a class="secondary-btn" href="/profile/'+p.id+'">View profile ↗</a><button class="button dark" id="account-bid">Top up sandbox bid</button></div>':'<p>Your profile will appear here once you save it.</p>')+'</section><section class="panel"><div class="panel-header"><h2>Outbid notifications <span class="notice-badge">'+n.filter(x=>!x.read).length+'</span></h2>'+(n.some(x=>!x.read)?'<button class="text-btn" id="mark-read">Mark read</button>':'')+'</div>'+(n.length?n.map(x=>'<div class="notification '+(!x.read?'unread':'')+'">'+esc(x.message)+'<time>'+esc(date(x.created))+'</time></div>').join(''):'<p>No notifications yet. We’ll show an update here when another profile overtakes you.</p>')+'<p>In-app notifications only. Email alerts are not connected.</p></section><section class="panel"><h2>Bid history</h2>'+(b.length?'<div class="scroll-table"><table class="history"><thead><tr><th>Date</th><th>Added</th><th>Mode</th></tr></thead><tbody>'+b.map(x=>'<tr><td>'+esc(date(x.created))+'</td><td>'+money(x.amount)+'</td><td>Sandbox</td></tr>').join('')+'</tbody></table></div>':'<p>No bids yet.</p>')+'</section><section class="panel"><h2>Profile analytics</h2><p><b>'+(account?.stats?.views||0)+'</b> profile-detail views · <b>'+(account?.stats?.clicks||0)+'</b> outbound clicks</p><p>Unique signed-in visitors per day, excluding you. These are Linkdid metrics, not LinkedIn analytics.</p></section></div></div></section>'+footer();
$('#profile-form').onsubmit=async e=>{e.preventDefault();const f=e.target,button=f.querySelector('button');button.disabled=true;$('#profile-error').textContent='';try{await api('/api/profile',Object.fromEntries(new FormData(f)));account=await api('/api/account');people=(await api('/api/profiles')).profiles;dashboard();toast('Profile saved.')}catch(err){$('#profile-error').textContent=err.message;}finally{button.disabled=false}};
if($('#photo-form'))$('#photo-form').onsubmit=async e=>{e.preventDefault();const f=e.target,photo=f.elements.photo.files[0],button=f.querySelector('button');if(!photo||photo.size>2*1024*1024){$('#photo-error').textContent='Choose an image under 2 MB.';return}button.disabled=true;$('#photo-error').textContent='';try{const r=await fetch('/api/photo',{method:'POST',body:photo,headers:{'content-type':photo.type}}),data=await r.json();if(!r.ok)throw Error(data.error);account=await api('/api/account');dashboard();toast('Photo uploaded.')}catch(err){$('#photo-error').textContent=err.message}finally{button.disabled=false}};
$('#account-refresh').onclick=async()=>{try{account=await api('/api/account');people=(await api('/api/profiles')).profiles;dashboard();toast('Dashboard refreshed.');}catch(e){toast(e.message)}};if($('#account-bid'))$('#account-bid').onclick=()=>openBid();if($('#mark-read'))$('#mark-read').onclick=async()=>{try{await api('/api/notifications/read',{});account=await api('/api/account');dashboard();}catch(e){toast(e.message)}};imageFallbacks();rulesBindings();}
function profilePage(){const id=location.pathname.split('/')[2],p=people.find(p=>p.id===id);if(!p){$('#app').innerHTML='<div class="page-state"><h2>Profile not found.</h2><a href="/">Back to the leaderboard</a></div>';return}document.title=p.name+' — Linkdid';$('#app').innerHTML='<section class="profile-detail"><a href="/">← Leaderboard</a><div class="panel" style="margin-top:24px">'+avatar(p)+'<h1>'+esc(p.name)+'</h1><p>'+esc(p.headline)+'</p><div class="meta"><span class="tag">'+esc(p.category)+'</span><span>'+esc(p.location)+'</span></div><div class="detail-total">'+money(p.bid)+'</div><p>Sandbox total · #'+p.rank+' all-time</p><div class="profile-actions"><a class="button dark" href="/go/'+p.id+'" target="_blank" rel="noopener">View on LinkedIn ↗</a><button class="secondary-btn" id="profile-bid">'+(p.id===account?.profile?.id?'Top up':'Outbid')+'</button><button class="secondary-btn" id="share-profile">Copy profile link</button></div><p class="detail-note">Self-submitted profile. LinkedIn account ownership has not been verified.</p></div></section>'+footer();$('#profile-bid').onclick=()=>openBid(p);$('#share-profile').onclick=async()=>{try{await navigator.clipboard.writeText(location.origin+'/profile/'+p.id);toast('Profile link copied.')}catch{toast('Copy this page’s address to share your profile.')}};imageFallbacks();rulesBindings();}
async function boot(){try{session=await api('/api/me');people=(await api('/api/profiles')).profiles;if(session.user)account=await api('/api/account');$('#account-link').textContent=session.user?'My dashboard ↗':'Sign in ↗';if(await commerceRoute())return;if(location.pathname==='/account')dashboard();else if(location.pathname.startsWith('/profile/')){profilePage();if(session.user)api('/api/view/'+location.pathname.split('/')[2],{}).catch(()=>{});}else home();}catch(e){$('#app').innerHTML='<div class="page-state"><h2>Linkdid is temporarily unavailable.</h2><p>'+esc(e.message)+'</p><button class="button dark" id="retry">Try again</button></div>';$('#retry').onclick=boot;}}
$('#rules-button').onclick=()=>$('#rules-dialog').showModal();document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());setInterval(()=>{if(document.visibilityState==='visible'&&location.pathname==='/')refresh();},30000);boot();
